/**
 * Full decrypted item.
 */
public struct ItemDetail {
    public var uuid: String
    public var title: String
    public var username: String?
    public var password: String?
    public var url: String?
    public var notes: String?
    public var totpSeed: String?
    public var favorite: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(uuid: String, title: String, username: String?, password: String?, url: String?, notes: String?, totpSeed: String?, favorite: Bool) {
        self.uuid = uuid
        self.title = title
        self.username = username
        self.password = password
        self.url = url
        self.notes = notes
        self.totpSeed = totpSeed
        self.favorite = favorite
    }
}

#if compiler(>=6)
extension ItemDetail: Sendable {}
#endif


extension ItemDetail: Equatable, Hashable {
    public static func ==(lhs: ItemDetail, rhs: ItemDetail) -> Bool {
        if lhs.uuid != rhs.uuid {
            return false
        }
        if lhs.title != rhs.title {
            return false
        }
        if lhs.username != rhs.username {
            return false
        }
        if lhs.password != rhs.password {
            return false
        }
        if lhs.url != rhs.url {
            return false
        }
        if lhs.notes != rhs.notes {
            return false
        }
        if lhs.totpSeed != rhs.totpSeed {
            return false
        }
        if lhs.favorite != rhs.favorite {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(uuid)
        hasher.combine(title)
        hasher.combine(username)
        hasher.combine(password)
        hasher.combine(url)
        hasher.combine(notes)
        hasher.combine(totpSeed)
        hasher.combine(favorite)
    }
}



