public enum VaultError: Swift.Error {

    
    
    case Kdf
    case Encrypt
    case Decrypt
    case InvalidSecretKey
    case Malformed
    case InvalidOptions
    case NotFound(String
    )
    case Io(String
    )
    case Json(String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeVaultError: FfiConverterRustBuffer {
    typealias SwiftType = VaultError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> VaultError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Kdf
        case 2: return .Encrypt
        case 3: return .Decrypt
        case 4: return .InvalidSecretKey
        case 5: return .Malformed
        case 6: return .InvalidOptions
        case 7: return .NotFound(
            try FfiConverterString.read(from: &buf)
            )
        case 8: return .Io(
            try FfiConverterString.read(from: &buf)
            )
        case 9: return .Json(
            try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: VaultError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .Kdf:
            writeInt(&buf, Int32(1))
        
        
        case .Encrypt:
            writeInt(&buf, Int32(2))
        
        
        case .Decrypt:
            writeInt(&buf, Int32(3))
        
        
        case .InvalidSecretKey:
            writeInt(&buf, Int32(4))
        
        
        case .Malformed:
            writeInt(&buf, Int32(5))
        
        
        case .InvalidOptions:
            writeInt(&buf, Int32(6))
        
        
        case let .NotFound(v1):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .Io(v1):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .Json(v1):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(v1, into: &buf)
            
        }
    }
}


